   where c.code = 'aflac' and c.organization_id is null
     and not exists (select 1 from public.carrier_layout_assignment a where a.tenant_id is null and a.carrier_id = c.id and a.file_type = 'commissions');
  insert into public.carrier_layout_assignment (tenant_id, carrier_id, file_type, layout_key)
  select null, c.id, 'commissions', 'commission_detail_2sheet' from public.carriers c
   where c.code = 'american_home_life' and c.organization_id is null
