-- ─── self-check ────────────────────────────────────────────────────────────────────────────────
do $$
begin
  if (select count(*) from public.carrier_layout_map where tenant_id is null and layout_key in ('policy_summary_46', 'commission_detail_2sheet', 'amam_policies_csv', 'amam_advances_csv', 'americo_policies_xlsx', 'americo_statement_pdf', 'corebridge_policy_summary', 'corebridge_new_business', 'corebridge_statement_pdf', 'moo_policy_csv_76', 'moo_ebssr_details', 'ssl_policy_list_xls', 'ssl_statement_pdf')) <> 13 then
    raise exception '20261009110000: not every layout was seeded';
  end if;
  if position('new.pdf_layout is distinct from old.pdf_layout' in pg_get_functiondef('public.carrier_layout_map_guard()'::regprocedure)) = 0 then
    raise exception '20261009110000: a published map''s PDF layout is not frozen';
  end if;
  if (select count(*) from public.carrier_layout_map where tenant_id is null and pdf_layout is not null and layout_key in ('americo_statement_pdf', 'corebridge_statement_pdf', 'ssl_statement_pdf')) <> 3 then
    raise exception '20261009110000: a PDF layout is missing';
  end if;
  if (select count(*) from public.carrier_layout_map_entry e join public.carrier_layout_map m on m.id = e.map_id where m.tenant_id is null and m.layout_key in ('policy_summary_46', 'commission_detail_2sheet', 'amam_policies_csv', 'amam_advances_csv', 'americo_policies_xlsx', 'americo_statement_pdf', 'corebridge_policy_summary', 'corebridge_new_business', 'corebridge_statement_pdf', 'moo_policy_csv_76', 'moo_ebssr_details', 'ssl_policy_list_xls', 'ssl_statement_pdf')) <> 147 then
    raise exception '20261009110000: the layouts do not have all their columns';
  end if;
  if (select count(*) from public.carrier_layout_assignment a join public.carriers c on c.id = a.carrier_id where a.tenant_id is null and c.organization_id is null and c.code in ('aetna', 'aflac', 'american_home_life', 'american_amicable', 'americo', 'corebridge', 'mutual_of_omaha', 'sentinel_security_life')) < 17 then
    raise exception '20261009110000: not every carrier has its layouts assigned';
  end if;
end $$;
